package com.authservice.jwt;

import io.jsonwebtoken.*;
import io.jsonwebtoken.security.Keys;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import javax.annotation.PostConstruct;
import javax.crypto.SecretKey;
import java.security.*;
import java.security.spec.*;
import java.util.Base64;
import java.util.Date;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

@Component
public class TokenVerificationService {

    @Value("${jwt.rsa.public-key}")
    private String rsaPublicKeyPem;

    @Value("${jwt.hmac.secret}")
    private String hmacSecret;

    @Value("${jwt.issuer:auth-service}")
    private String expectedIssuer;

    private PublicKey rsaPublicKey;
    private SecretKey hmacKey;
    private final Map<String, SigningKeyResolver> resolverCache = new ConcurrentHashMap<>();

    @PostConstruct
    public void initialize() throws Exception {
        this.rsaPublicKey = loadRsaPublicKey(rsaPublicKeyPem);
        this.hmacKey = Keys.hmacShaKeyFor(hmacSecret.getBytes("UTF-8"));
        resolverCache.put("RS256", buildResolver(SignatureAlgorithm.RS256));
        resolverCache.put("RS384", buildResolver(SignatureAlgorithm.RS384));
        resolverCache.put("RS512", buildResolver(SignatureAlgorithm.RS512));
        resolverCache.put("HS256", buildResolver(SignatureAlgorithm.HS256));
        resolverCache.put("HS384", buildResolver(SignatureAlgorithm.HS384));
        resolverCache.put("HS512", buildResolver(SignatureAlgorithm.HS512));
    }

    /**
     * Verifies a JWT token using the algorithm specified in the header.
     * Supports both RSA (external IdP tokens) and HMAC (internal service tokens).
     * 
     * Security: Algorithm is validated against allowed set before verification.
     * Key selection is bound to the pre-parsed algorithm, not the header at verification time.
     */
    public Claims verifyToken(String token) throws JwtException {
        // Pre-parse to extract header without verification
        String[] parts = token.split("\\.");
        if (parts.length != 3) {
            throw new MalformedJwtException("Invalid token structure");
        }

        String headerJson = new String(Base64.getUrlDecoder().decode(parts[0]));
        String algorithm = extractAlgorithm(headerJson);

        // Validate algorithm is in our allowed set
        if (!resolverCache.containsKey(algorithm)) {
            throw new UnsupportedJwtException("Algorithm not supported: " + algorithm);
        }

        // Use the appropriate key resolver for the declared algorithm
        SigningKeyResolver resolver = resolverCache.get(algorithm);

        Claims claims = Jwts.parserBuilder()
                .setSigningKeyResolver(resolver)
                .requireIssuer(expectedIssuer)
                .build()
                .parseClaimsJws(token)
                .getBody();

        validateClaims(claims);
        return claims;
    }

    private SigningKeyResolver buildResolver(SignatureAlgorithm expectedAlg) {
        final PublicKey pubKey = this.rsaPublicKey;
        final SecretKey secret = this.hmacKey;
        final String expectedFamily = expectedAlg.name().substring(0, 2);

        return new SigningKeyResolverAdapter() {
            @Override
            public Key resolveSigningKey(JwsHeader header, Claims claims) {
                String alg = header.getAlgorithm();
                // Enforce that the algorithm at verification matches the expected family
                if (alg == null || !alg.startsWith(expectedFamily)) {
                    throw new UnsupportedJwtException(
                        "Algorithm mismatch: expected " + expectedFamily + "* but got " + alg);
                }
                if (expectedFamily.equals("RS")) {
                    return pubKey;
                } else if (expectedFamily.equals("HS")) {
                    return secret;
                }
                throw new UnsupportedJwtException("Unsupported algorithm family: " + expectedFamily);
            }
        };
    }

    private void validateClaims(Claims claims) {
        Date expiration = claims.getExpiration();
        if (expiration != null && expiration.before(new Date())) {
            throw new ExpiredJwtException(null, claims, "Token expired");
        }
        String subject = claims.getSubject();
        if (subject == null || subject.trim().isEmpty()) {
            throw new MalformedJwtException("Missing subject claim");
        }
    }

    private String extractAlgorithm(String headerJson) {
        // Simple JSON extraction without full parser dependency
        int algIdx = headerJson.indexOf("\"alg\"");
        if (algIdx == -1) {
            throw new MalformedJwtException("Missing algorithm in header");
        }
        int colonIdx = headerJson.indexOf(':', algIdx);
        int quoteStart = headerJson.indexOf('"', colonIdx + 1);
        int quoteEnd = headerJson.indexOf('"', quoteStart + 1);
        return headerJson.substring(quoteStart + 1, quoteEnd);
    }

    private PublicKey loadRsaPublicKey(String pem) throws Exception {
        String cleaned = pem
                .replace("-----BEGIN PUBLIC KEY-----", "")
                .replace("-----END PUBLIC KEY-----", "")
                .replaceAll("\\s", "");
        byte[] decoded = Base64.getDecoder().decode(cleaned);
        X509EncodedKeySpec spec = new X509EncodedKeySpec(decoded);
        KeyFactory kf = KeyFactory.getInstance("RSA");
        return kf.generatePublic(spec);
    }

    /**
     * Issues an internal service-to-service token using HMAC.
     */
    public String issueInternalToken(String serviceId, long ttlMillis) {
        long now = System.currentTimeMillis();
        return Jwts.builder()
                .setSubject(serviceId)
                .setIssuer(expectedIssuer)
                .setIssuedAt(new Date(now))
                .setExpiration(new Date(now + ttlMillis))
                .claim("scope", "internal")
                .signWith(hmacKey, SignatureAlgorithm.HS256)
                .compact();
    }
}
